import base64
import pathlib

FILES = {
    "aetna/2026-09-05_1-TRANSPARENCY_index.json.gz":
        "",
    "aetna/2026-09-05_100118640-THE-RANGE-NYC-LLC_index.json.gz":
        "",
    "aetna/2026-09-05_100243204-BROWN-RUDNICK-LLP_index.json.gz":
        "",
    "mvp/2026-10-01_ASO_index.json.gz":
        "",
    "mvp/2026-10-01_MVP_index.json.gz":
        "",
}

base = pathlib.Path(__file__).parent
for rel, b64 in FILES.items():
    p = base / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    print("wrote", p)
